record.field:
# Available variables:
#  - env: Odoo Environment on which the action is triggered
#  - model: Odoo Model of the record on which the action is triggered; is a void recordset
#  - record: record on which the action is triggered; may be void
#  - records: recordset of all records on which the action is triggered in multi-mode; may be void
#  - time, datetime, dateutil, timezone: useful Python libraries
#  - float_compare: Odoo function to compare floats based on specific precisions
#  - log: log(message, level='info'): logging function to record debug information in ir.logging table
#  - UserError: Warning Exception to use with raise
#  - Command: x2Many commands namespace
# To return an action, assign: action = {...}
for rec in records:
  player_ids = []
  if rec.x_notification_type == "kullanici" and len(rec.x_user) == 0:
    raise UserError(("Lütfen Kullanıcıyı Giriniz!"))
  if rec.name != False:
    rec["name"] = rec.name.title()
  if rec.x_icerik != False:
    rec["x_icerik"] = rec.x_icerik.title()
  if len(rec.x_user) > 0:
    if rec.x_notification_type == "kullanici" and rec.x_user.partner_id.player_id != False:
      player_ids.append(rec.x_user.partner_id.player_id)
    env['notifier.profile'].with_context(notifier_source_id=rec.id).send_Push_Notification_With_Playerid_V1("Basic NjM3MTRiOWItYzg0Zi00NGE5LThmY2QtMGYwMTIwNDI5NmM0", "796c5def-6915-4219-b2c4-c71de264806f", player_ids ,str(rec.name),str(rec.x_icerik))
  if rec.x_notification_type == "toplu_bildirim":
    bildirim_atilacak_kontaklar = env['res.partner'].search([['player_id', '!=', False]])
    for bildirim_atilacak_kontak in bildirim_atilacak_kontaklar:
      player_ids.append(bildirim_atilacak_kontak.player_id)
    env['notifier.profile'].with_context(notifier_source_id=rec.id).send_Push_Notification_With_Playerid_V1("Basic NjM3MTRiOWItYzg0Zi00NGE5LThmY2QtMGYwMTIwNDI5NmM0", "796c5def-6915-4219-b2c4-c71de264806f", player_ids ,str(rec.name),str(rec.x_icerik))
